// TH14 synthetic training aliases: native type 10 -> TH14_SHARD (row base 512).
// Native 0..23 map to the same target row; this is an approved synthetic mapping.
const TH14_SHARD: int = 512;

const TIME_LIMIT: int = 1624;
const OPENING_BUFFER: int = 120;

// Native ACCEL (EX type 4): a=120 frames, r=0.033333335, s=F2-pi (fixed direction).
// Target keeps the fixed direction as a cartesian per-frame velocity increment; the
// source ANIM spawn step (a=1) itself is birth-stage and omitted, so ACCEL starts at birth.
xformdef ACCEL120(gx: fx, gy: fx) {
    @120 set_gravity(gx, gy); // @N is the post-delay of this op: apply for 120 frames
    stop_fx();
}

// st05.ecl.txt MainSub01 553-578: two batches of 10 ECir00, 10 frames apart,
// batch1 y=360 from source frame 0, batch2 y=300 from source frame 260.
async sub pattern() {
    wait(OPENING_BUFFER);

    var f0: fx = -160fx;
    var f2b: int = 16384; // source %F2 = +pi/2
    for i in 0..10 {
        f0 = f0 + 32fx;
        var u1: fx = (rand(65536) - 32768) as fx / 32768;
        _ = spawn_enemy(0fx, 360fx, 160, 0, 0, 0, ecir00(f0, u1 * 32fx, f2b, 360fx));
        wait(10);
    }
    wait(160);

    f0 = 160fx;
    f2b = 16384;
    for j in 0..10 {
        f0 = f0 - 32fx;
        var u2: fx = (rand(65536) - 32768) as fx / 32768;
        _ = spawn_enemy(0fx, 300fx, 160, 0, 0, 0, ecir00(f0, u2 * 32fx - 64fx, f2b, 300fx));
        f2b = 0 - f2b; // source flips %F2 after each batch-2 creation
        wait(10);
    }
}

// st05.ecl.txt ECir00 14-47 (movement/boxes/et setup; ANM and drops omitted by policy).
async sub ecir00(f0: fx, f1: fx, f2b: int, y0: fx) {
    set_invuln(65535);
    set_hurtbox(12fx); // source setHurtbox(24,24): circle radius 12
    set_hitbox(8fx);   // source setHitbox(16,16): circle radius 8
    set_enemy_flag(ENEMY_NO_BODY, 1); // source flagSet(15) before the 160-frame wait

    // movePosRel(160+RANDF2*32, RANDF2*64): immediate REL write = start point.
    var ux: fx = (rand(65536) - 32768) as fx / 32768;
    var uy: fx = (rand(65536) - 32768) as fx / 32768;
    move_to(0, 160fx + ux * 32fx, y0 + uy * 64fx, EASE_LINEAR);
    // movePosRelTime(160, mode1=t^2, %F0, %F1): REL interpolates to the inherited F0/F1.
    move_to(160, f0, y0 + f1, EASE_QUAD_IN);
    wait(160);

    set_enemy_flag(ENEMY_NO_BODY, 0); // source flagClear(15)
    spawn ecir00_at(f2b);
    wait(120);

    // moveVel(ANGLE_PLAYER, 0); moveSpeedTime(120, 0, 3.0)
    move_vel(0, aim_player(), 0fx, EASE_LINEAR);
    move_speed(120, 3fx, EASE_LINEAR);
    loop { wait(1000); }
}

// st05.ecl.txt ECir00_at 49-81: two volleys, 4 frames apart; per-volley base jitter
// RANDF2*0.17453292 and fixed fan spread 0.17453292 (both ~1820 BAM).
async sub ecir00_at(f2b: int) {
    var n: int = global(GVAR_RANK) * 2 + 1; // source count 1/3/5/7 for E/N/H/L
    var s: angle = (f2b - 32768) as angle;  // source %F2 - pi
    var gx: fx = 0.033333335fx * cos(s);
    var gy: fx = 0.033333335fx * sin(s);

    wait(10);
    var vol: int = 0;
    while vol < 2 { // source $I0 = 2
        var base: int = f2b + (rand(65536) - 32768) * 1820 / 32768;
        for i in 0..n { // source mode1 fan F(N,i): 0,-d,+d,-2d,+2d...
            var off: int = ((i + 1) / 2) * 1820;
            if i % 2 != 0 { off = 0 - off; }
            var a: angle = (base + off) as angle;
            // ANIM a=1 keeps its spawn backstep position -= 4*velocity (speed 2 -> 8px back).
            _ = fire(TH14_SHARD, 6,
                     $self_x - 8fx * cos(a), $self_y - 8fx * sin(a),
                     2fx, a, ACCEL120(gx, gy), none);
        }
        vol = vol + 1;
        wait(4);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
